  ('Belgian Tripel', 'Trappist Ale', 'A pale, somewhat spicy, dry, strong Belgian ale with a pleasant rounded malt flavor.', 1.075, 1.085, 1.008, 1.014, 7.5, 9.5, 20, 40, 4.5, 7, true),
  ('Belgian Dark Strong Ale', 'Trappist Ale', 'A dark, complex, very strong Belgian ale with a delicious blend of malt richness, dark fruit flavors, and spicy notes.', 1.075, 1.11, 1.01, 1.024, 8, 12, 20, 35, 12, 22, true),
