-- Fix BJCP styles that already existed
-- Updates is_bjcp flag and vital stats for BJCP style names

-- First, ensure the column exists
ALTER TABLE beer_styles ADD COLUMN IF NOT EXISTS is_bjcp boolean DEFAULT false;

-- Update existing styles to mark as BJCP and set their vital stats
-- Using ON CONFLICT to upsert

-- Delete all existing and re-insert with proper data
DELETE FROM beer_styles WHERE name IN (
  'American Light Lager', 'American Lager', 'Cream Ale', 'American Wheat Beer',
  'International Pale Lager', 'International Amber Lager', 'International Dark Lager',
  'Czech Pale Lager', 'Czech Premium Pale Lager', 'Czech Amber Lager', 'Czech Dark Lager',
  'Munich Helles', 'Festbier', 'Helles Bock', 'German Leichtbier', 'Kölsch',
