  'Vienna Lager', 'Altbier', 'Kellerbier', 'Munich Dunkel', 'Schwarzbier',
  'Doppelbock', 'Eisbock', 'Baltic Porter', 'Weissbier', 'Dunkles Weissbier',
  'Weizenbock', 'Ordinary Bitter', 'Best Bitter', 'Strong Bitter', 'British Golden Ale',
  'Australian Sparkling Ale', 'English IPA', 'Dark Mild', 'British Brown Ale',
  'English Porter', 'Scottish Light', 'Scottish Heavy', 'Scottish Export',
  'Irish Red Ale', 'Irish Stout', 'Irish Extra Stout', 'Sweet Stout', 'Oatmeal Stout',
  'Tropical Stout', 'Foreign Extra Stout', 'British Strong Ale', 'Old Ale',
  'Wee Heavy', 'English Barleywine', 'Blonde Ale', 'American Pale Ale',
  'American Amber Ale', 'California Common', 'American Brown Ale', 'American Porter',
  'American Stout', 'Imperial Stout', 'American IPA', 'Specialty IPA', 'Hazy IPA',
  'Double IPA', 'American Strong Ale', 'American Barleywine', 'Wheatwine',
  'Berliner Weisse', 'Flanders Red Ale', 'Oud Bruin', 'Lambic', 'Gueuze',
  'Fruit Lambic', 'Gose', 'Witbier', 'Belgian Pale Ale', 'Bière de Garde',
  'Belgian Blond Ale', 'Saison', 'Belgian Golden Strong Ale', 'Belgian Single',
  'Belgian Dubbel', 'Belgian Tripel', 'Belgian Dark Strong Ale', 'Trappist Single',
  'Mixed-Fermentation Sour Beer', 'Wild Specialty Beer', 'Fruit Beer',
  'Fruit and Spice Beer', 'Specialty Fruit Beer', 'Grape Ale', 'Spice, Herb, or Vegetable Beer',
  'Autumn Seasonal Beer', 'Winter Seasonal Beer', 'Alternative Grain Beer',
  'Alternative Sugar Beer', 'Classic Style Smoked Beer', 'Specialty Smoked Beer',
  'Commercial Specialty Beer', 'Mixed-Style Beer', 'Experimental Beer',
